  (1, '360-move-uluwatu', 'why_its_here', (select count(*)::int from venues where slug = '360-move-uluwatu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'd74127cdc0e3bd850c31833d14eb77e6'), md5('A community-minded gym and training centre in Pecatu, on Jalan Pantai Suluban, with two levels of equipment and an outdoor workout area. Classes cover a lot of ground: strength and conditioning, Hot Pilates, spin, HIIT, Muay Thai and BJJ.') = '02dc53513da052a64e4a44123787096a'),
  (2, '360-move-uluwatu', 'best_for', (select count(*)::int from venues where slug = '360-move-uluwatu' and status = 'active' and publication_status = 'published' and md5(best_for) = '77ed64d995b753ce96c6b48e5ce8c675'), md5('Training that mixes open-gym sessions with group classes across many disciplines, in one place') = '1afb14932a240c533c8cc646dc416ff3'),
  (3, 'ami-studio', 'why_its_here', (select count(*)::int from venues where slug = 'ami-studio' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '335746d8c0787a9e742a7705c10eb22d'), md5('Reformer and mat Pilates, plus barre, in an ocean-view studio in Uluwatu. Classes run in small groups and focus on strength, balance and controlled movement.') = '173c97567d3fff16a0db7d0d827dd82b'),
  (4, 'ami-studio', 'best_for', (select count(*)::int from venues where slug = 'ami-studio' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b8fbaddee409f7b645b6c0fff28f8589'), md5('A calm reformer or barre class in a boutique studio') = '5caa2be23d1f56cac99360ac659303eb'),
  (5, 'andaz-bali-fitness-centre', 'why_its_here', (select count(*)::int from venues where slug = 'andaz-bali-fitness-centre' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'b1a7a14bd571f21e66a2128228ed284c'), md5('Andaz Bali in Sanur has no gym of its own, so its guests train next door at the Hyatt Regency. The Shankha Spa fitness centre there is open 24 hours, with about 2,000 sq ft of Precor machines. Free sunrise yoga runs on the beach.') = 'affa44596f4f4a33aaf2f53cf9647f49'),
  (6, 'andaz-bali-fitness-centre', 'best_for', (select count(*)::int from venues where slug = 'andaz-bali-fitness-centre' and status = 'active' and publication_status = 'published' and md5(best_for) = 'ddbb17632efcab740fdd5e684723d5b3'), md5('Andaz guests who want a full 24-hour gym and are happy to walk next door through the side entrance') = '1776d2dcb3f9fde5ebd172f9a1c5553f'),
  (7, 'aroma-spa-retreat-sanur', 'why_its_here', (select count(*)::int from venues where slug = 'aroma-spa-retreat-sanur' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '1f7ba69f145c6deded607130b79403bc'), md5('A day spa in a Sanur garden, with Balinese massage and other treatments. The setting is quiet and the pace unhurried.') = '96bd2352993f9edfa29229a3d61bf40b'),
  (8, 'aroma-spa-retreat-sanur', 'best_for', (select count(*)::int from venues where slug = 'aroma-spa-retreat-sanur' and status = 'active' and publication_status = 'published' and md5(best_for) = '77e1aae788a650e1f88cafb1f4580026'), md5('A Balinese massage when you''re based in Sanur') = '587e0670cc4a913b6d7a83cadd1fa4f8'),
  (9, 'babi-guling-odah-sanur', 'why_its_here', (select count(*)::int from venues where slug = 'babi-guling-odah-sanur' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'cc274972f7478508392ba482e6f5fc1b'), md5('A Balinese roast-pork warung near Pasar Sindhu, with an unusually wide babi guling range. Plates are finished with the house sambal tabia: chili, roasted shrimp paste and lime.') = 'a1c27f6665999ddba6c6d4dbccbbd4fb'),
  (10, 'babi-guling-odah-sanur', 'best_for', (select count(*)::int from venues where slug = 'babi-guling-odah-sanur' and status = 'active' and publication_status = 'published' and md5(best_for) = 'bdea731435bc1187b3aa38f70d450580'), md5('A quick, cheap Balinese lunch for pork lovers and babi guling specialists, solo diners included') = 'd8dbc1009aa1bf63fc4d058f2aa8c063'),
  (11, 'babi-guling-odah-sanur', 'not_for', (select count(*)::int from venues where slug = 'babi-guling-odah-sanur' and status = 'active' and publication_status = 'published' and md5(not_for) = 'ecaa1d6151ee3f3edb3b441af04b023c'), md5('Vegetarian, halal and no-pork diets, or anyone wanting a broad or Western menu: this is a babi guling warung') = '2cda70508f9d429835859fe990e68842'),
