  (13, 'bali-barber-sanur-sanur', 'best_for', (select count(*)::int from venues where slug = 'bali-barber-sanur-sanur' and status = 'active' and publication_status = 'published' and md5(best_for) = '0c28d5db832240ac21107736fe072975'), md5('Men who want a barber cut or a shave with a coffee, beer or cocktail while they wait') = '0d988b470589b451e61657ba64d47ea7'),
  (14, 'balique-restaurant', 'why_its_here', (select count(*)::int from venues where slug = 'balique-restaurant' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'ba6cb974615875f42c0dd12e0dffdc08'), md5('Belgian couple Blaise Samoy and Zohra Boukhari opened this roadside cafe-restaurant in Jimbaran''s fishing village in 2012. Antiques they collected across the archipelago fill a vintage European and colonial interior. The menu is mostly Indonesian, with a multi-dish rijsttafel, plus European and fusion plates.') = 'f8d6ac20a4a2a0ae561a1e7b856c80c1'),
  (15, 'balique-restaurant', 'best_for', (select count(*)::int from venues where slug = 'balique-restaurant' and status = 'active' and publication_status = 'published' and md5(best_for) = '755bc65265711ff926f6160859c6ccb1'), md5('A lunch or dinner of Indonesian home-style cooking, away from the beachfront') = '8935fff0f19edf7bfece474c5c5ee51a'),
  (16, 'bambu-fitness-bali', 'why_its_here', (select count(*)::int from venues where slug = 'bambu-fitness-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'e6c7c7837e9975293ec0c1285c08694e'), md5('A large open-plan bamboo gym in the Pecatu and Bingin area. Rogue and Eleiko gear fills zones for Olympic weightlifting, functional fitness and cardio. Group classes include CrossFit and Hyrox, and the site has a cafe plus a sauna and cold plunge for recovery.') = 'be02803be18b1da61e254f8ebda0fe32'),
  (17, 'bambu-fitness-bali', 'best_for', (select count(*)::int from venues where slug = 'bambu-fitness-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '08fac15636a42326acad04d2921971e6'), md5('Lifters and CrossFit or Hyrox fans who want a full-featured strength gym with a social feel') = 'c6751fdb529cced9e460b7348ccc4112'),
  (18, 'banana-lounge-bali-uluwatu-bukit', 'why_its_here', (select count(*)::int from venues where slug = 'banana-lounge-bali-uluwatu-bukit' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'f5500e830660d63ca5ed41388a70cbe4'), md5('A beach club on the Bukit with lounges and sunbeds in a tropical setting. Food and drinks are served, and you book on the venue''s own website.') = 'e9351562b34abedde87640e7e97179e2'),
  (19, 'banana-lounge-bali-uluwatu-bukit', 'best_for', (select count(*)::int from venues where slug = 'banana-lounge-bali-uluwatu-bukit' and status = 'active' and publication_status = 'published' and md5(best_for) = '533089b4bdad21783a002816480b3063'), md5('A day of sun loungers, pool and drinks by the beach') = 'c855e459596b32180900756c223f513e'),
  (20, 'bella-cucina', 'why_its_here', (select count(*)::int from venues where slug = 'bella-cucina' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '4d6a71647ec8420578a1eb4fe40a2447'), md5('Italian fine dining at the InterContinental Bali Resort in Jimbaran. Handmade pastas and Mediterranean-leaning mains come from an open kitchen into an air-conditioned room lit by chandeliers. Sunday brunch has live music.') = 'f5ec5d701929b6ae72d843579ac05fcb'),
  (21, 'bella-cucina', 'best_for', (select count(*)::int from venues where slug = 'bella-cucina' and status = 'active' and publication_status = 'published' and md5(best_for) = '504d2239bc612949a87f4a15d413ef06'), md5('Couples and families dressing up for dinner, or taking their time over Sunday brunch') = '130177b2914935b0d1358de84419b119'),
  (22, 'bluvana-reformer-studio', 'why_its_here', (select count(*)::int from venues where slug = 'bluvana-reformer-studio' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'f3cc85c84a533731834ccc56eef261f3'), md5('Classes at this reformer studio on Jl. Pantai Cemongkak in Pecatu are capped at six reformers. There are eight 50-minute formats, each aimed at a zone or an energy level. Sessions run daily, morning and evening, and you book online.') = '199c0f0ac4843981f3a6f074238cdd03'),
  (23, 'd-nailbar-spa-uluwatu', 'why_its_here', (select count(*)::int from venues where slug = 'd-nailbar-spa-uluwatu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'f4a036e4c09b291acc4d76d24e3cca69'), md5('Near Padang Padang, on Jl. Labuansait, this nail bar does gel, BIAB, extensions and nail art. Lash and brow work is done here too, and it fills up, so book ahead on WhatsApp.') = 'c77ff85d7208b3db7c7e661fa42776b8'),
  (24, 'd-nailbar-spa-uluwatu', 'best_for', (select count(*)::int from venues where slug = 'd-nailbar-spa-uluwatu' and status = 'active' and publication_status = 'published' and md5(best_for) = 'ade153ea1c1e571cdebe870107f8c1a3'), md5('A gel manicure or nail art when you''re near Padang Padang or Uluwatu town') = '8a851d9fcb95d85eebe8c431b216afed'),
  (25, 'fisherman-s-club', 'best_for', (select count(*)::int from venues where slug = 'fisherman-s-club' and status = 'active' and publication_status = 'published' and md5(best_for) = '3afd7eb1bdcf66004ace692e642186f8'), md5('A seafood meal beside Sanur beach') = 'a7be8845e44683bcccc8ffa09cd6c126'),
  (26, 'fitness-plus', 'why_its_here', (select count(*)::int from venues where slug = 'fitness-plus' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'a309e0db72a30bd37ecc0c4723a2832f'), md5('Open 24 hours, this Sanur gym on Bypass Ngurah Rai has modern equipment, locker rooms and a sauna. Local trainers run group classes and personal training.') = '33b73b919634969272615bd676d01b2b'),
  (27, 'fitness-plus', 'best_for', (select count(*)::int from venues where slug = 'fitness-plus' and status = 'active' and publication_status = 'published' and md5(best_for) = 'bb530fe21817e8f5328ebf0e91334c3e'), md5('A workout at any hour, day or night') = '7db85899f2b9fba6395af0a8e327e165'),
  (28, 'garuda-wisnu-kencana', 'why_its_here', (select count(*)::int from venues where slug = 'garuda-wisnu-kencana' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'dc0586bfc6347430f60bbdb02f3a921f'), md5('A cultural park in Ungasan, Badung, built around a giant bronze statue of Vishnu and Garuda. The grounds also hold an amphitheatre and event spaces.') = '79333ab55f9303566dd1bf39edfaea09'),
  (29, 'garuda-wisnu-kencana', 'best_for', (select count(*)::int from venues where slug = 'garuda-wisnu-kencana' and status = 'active' and publication_status = 'published' and md5(best_for) = 'fcf173245c257d839bba612628e48eb9'), md5('Seeing the GWK statue up close, as part of a day out on the Bukit peninsula') = 'fe98f3fd51cf0434cb5951ab19029d5a'),
  (30, 'genius-cafe', 'why_its_here', (select count(*)::int from venues where slug = 'genius-cafe' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'e0fd6da3b1a733ffbd8135d179bbad1b'), md5(U&'A beachfront cafe and co-working space at Mertasari Beach in south Sanur, open daily 7am\201310pm. The Wi-Fi is fast, the menu is plant-forward all day, and you can sit with your toes in the sand without a beach-club minimum spend.') = '939b44821fe6f2850afae9b60f94b875'),
  (31, 'genius-cafe', 'best_for', (select count(*)::int from venues where slug = 'genius-cafe' and status = 'active' and publication_status = 'published' and md5(best_for) = '2136ecbae8e7a692198c307b1862591e'), md5('A laptop day by the sand for remote workers, or a daytime coffee or smoothie for plant-based eaters') = 'b6cbb5ad6f2749711d6d230cc0e0c75c'),
  (32, 'genius-cafe', 'not_for', (select count(*)::int from venues where slug = 'genius-cafe' and status = 'active' and publication_status = 'published' and md5(not_for) = 'e25ad39518009b9705258ca455ff415e'), md5('A formal dinner or a traditional warung meal: it''s a beach cafe with a plant-forward menu') = '980063b1c43f41e2f5348bf839df4986'),
