  (34, 'glo-day-spa-salon-sanur-sanur', 'best_for', (select count(*)::int from venues where slug = 'glo-day-spa-salon-sanur-sanur' and status = 'active' and publication_status = 'published' and md5(best_for) = '15b59b9cff3274273582ed5cfc9eec0c'), md5('A haircut, mani-pedi, waxing or brow work with a massage in one Western-style visit, or a bridal party getting ready for the day') = '2c36f06e6f208b120fa712199fc04709'),
