  (36, 'gong-restaurant', 'why_its_here', (select count(*)::int from venues where slug = 'gong-restaurant' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '8bb56ca3acfc2b973fb522c44dcf3357'), md5(U&'Kayumanis Sanur''s Indonesian and Balinese restaurant, on Jl. Tirta Akasa No. 28, open daily 7am\201310pm. The resort setting is intimate and the menu centres on traditional dishes.') = '5c94397957e34ccca5f46db4a7fdd1fc'),
  (37, 'gong-restaurant', 'best_for', (select count(*)::int from venues where slug = 'gong-restaurant' and status = 'active' and publication_status = 'published' and md5(best_for) = 'ac6e44d70af79caee90fb57135aabad0'), md5('A special evening of traditional Balinese food for a couple or a small party') = '7a3ef7d9e0f3e25f0e643f3741d7cb69'),
  (38, 'gong-restaurant', 'not_for', (select count(*)::int from venues where slug = 'gong-restaurant' and status = 'active' and publication_status = 'published' and md5(not_for) = '94ec31fcca7d6bcb181ef2f8b36424d1'), md5('A quick casual bite or a large, loud group. It is an intimate resort restaurant') = 'f85da0ce7afb72a276761058d0525110'),
  (39, 'good-hair-day-sanur', 'why_its_here', (select count(*)::int from venues where slug = 'good-hair-day-sanur' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'fcb5e98f27d328af0e4e80b6112753e1'), md5('At this hair salon on the Sanur strip, the stylists speak English and do cuts and colour.') = '9615c0058258924ad2df7e4a195b7545'),
  (40, 'good-hair-day-sanur', 'best_for', (select count(*)::int from venues where slug = 'good-hair-day-sanur' and status = 'active' and publication_status = 'published' and md5(best_for) = '11d5ad3e2ba05c4786503b3b1fbac9eb'), md5('A haircut along the Sanur strip without a language barrier') = '100b554506782a681faaf27d366dc844'),
