  (42, 'holiday-inn-bali-sanur-gym', 'best_for', (select count(*)::int from venues where slug = 'holiday-inn-bali-sanur-gym' and status = 'active' and publication_status = 'published' and md5(best_for) = '4c0c576e7695528d68d67a7869b20da2'), md5('Hotel guests keeping a light routine ticking over') = '60bb8af39f5172771d972894af30e864'),
