  (45, 'island-grooming-barbershop', 'best_for', (select count(*)::int from venues where slug = 'island-grooming-barbershop' and status = 'active' and publication_status = 'published' and md5(best_for) = 'e6bab51207773275445ae517effdeccc'), md5('A haircut, fade or beard trim near Uluwatu town or Bingin beach') = 'd7d08cce4f8670d69d4eabf4769c2588'),
