  (47, 'karma-spa-at-karma-kandara', 'best_for', (select count(*)::int from venues where slug = 'karma-spa-at-karma-kandara' and status = 'active' and publication_status = 'published' and md5(best_for) = 'e2d67d72b7546a60604469be8986d49a'), md5('A full spa day with cliff views and use of the sauna and pool') = 'e68d724f544980ec1f3ca56cdeabc4c5'),
