  (49, 'ko-japanese-teppanyaki-and-sushi', 'best_for', (select count(*)::int from venues where slug = 'ko-japanese-teppanyaki-and-sushi' and status = 'active' and publication_status = 'published' and md5(best_for) = '5f94909cd7f487a892ef21f25126bbc0'), md5('A couple or a group sharing a teppanyaki dinner at the counter, or sushi from the bar') = 'd96b3ba4b07d6f10cb573cff1610a850'),
  (50, 'koa-shala-sanur', 'why_its_here', (select count(*)::int from venues where slug = 'koa-shala-sanur' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '439c860cbceaa29a8f0a3a48af1d997b'), md5('A yoga shala and holistic wellness centre in a tropical garden off Jl. Danau Tamblingan. Three open-air yoga classes run every day, plus meditation in the courtyard.') = 'af85013a2424e590a87b3422ea89948a'),
