  (52, 'koa-shala-spa-sanur', 'why_its_here', (select count(*)::int from venues where slug = 'koa-shala-spa-sanur' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'b561f1480eca925cda24305fd94d46f6'), md5('Koa Shala''s spa does Balinese and holistic massage in a quiet courtyard. It sits down a banana-palm-lined lane off Jl. Danau Tamblingan, in central Sanur.') = '3de1b72bef70905fc38b45cc659ae21f'),
  (53, 'koa-shala-spa-sanur', 'best_for', (select count(*)::int from venues where slug = 'koa-shala-spa-sanur' and status = 'active' and publication_status = 'published' and md5(best_for) = 'a5cd0d03ca54a11c81e7a8fcd1254dd3'), md5('A calm, unhurried massage in a garden, often paired with a yoga class at the same address') = '63cd32b4782b475c93ffda00fd6a242c'),
  (54, 'kuu-izakaya-dining', 'why_its_here', (select count(*)::int from venues where slug = 'kuu-izakaya-dining' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'f7f9dddf24cf360f1bac5473245cc974'), md5('A Japanese izakaya-style restaurant at Maya Sanur Resort & Spa. The kitchen turns out sushi, sashimi, robatayaki skewers and tempura, and there''s sake and cocktails to drink.') = 'f315f9d83516c2a12bad36c67f3739c9'),
  (55, 'kuu-izakaya-dining', 'best_for', (select count(*)::int from venues where slug = 'kuu-izakaya-dining' and status = 'active' and publication_status = 'published' and md5(best_for) = '954f8c972a545ed7d30144c2abe5004a'), md5('Groups sharing Japanese plates, or a couple''s evening out over sushi and grilled skewers') = '06a82442748848b8391b4498f60d651a'),
  (56, 'kuu-izakaya-dining', 'not_for', (select count(*)::int from venues where slug = 'kuu-izakaya-dining' and status = 'active' and publication_status = 'published' and md5(not_for) = 'e42619bce0d5c61cbef5b1a33020d1ea'), md5('A quick, casual or budget meal: this is a resort restaurant') = '83468c279e042af101b35dfb08bcbeb8'),
