  (59, 'la-tribu-bali', 'best_for', (select count(*)::int from venues where slug = 'la-tribu-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = 'e6594de92e5b63c241b8dee15040836f'), md5('Playful classes for the movement-curious, with a pottery or painting workshop on the side') = 'cd1595781a8804a37392d71682fb3f80'),
  (60, 'leha-leha-spa-sanur', 'why_its_here', (select count(*)::int from venues where slug = 'leha-leha-spa-sanur' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '7eefa0c46dd2a80079d9911b937eb18c'), md5('Massage and other treatments at local prices, in a neighbourhood day spa near Sanur''s beach path.') = '84d4f9c1584c83fa6eda09dfa0cae3e3'),
  (61, 'leha-leha-spa-sanur', 'best_for', (select count(*)::int from venues where slug = 'leha-leha-spa-sanur' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b2079ffc13567c250dbdca892ef00cf8'), md5('An easy, affordable massage after a walk along the beach path') = 'c724d1b9a7d005b3e488827d56de441c'),
  (62, 'lilla-pantai', 'why_its_here', (select count(*)::int from venues where slug = 'lilla-pantai' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'e35cf462d10253b5eb50de20e2f2f68f'), md5('Tables face the sea at this beachfront restaurant on Sanur''s paved coastal walk, at Jalan Duyung. The kitchen cooks Indonesian and European dishes and seafood without MSG, from breakfast to late evening.') = '7c2645bcff8c656144dfbddce11da7a5'),
  (63, 'lilla-pantai', 'best_for', (select count(*)::int from venues where slug = 'lilla-pantai' and status = 'active' and publication_status = 'published' and md5(best_for) = 'ad59d17465c013e3c35dd1c6dbe45142'), md5('Couples, families and long-stay visitors who want an easy seafront meal without a resort setting') = 'fbf70827718984a8cb446f8b0e782f9b'),
