  (65, 'linga-longa-bar', 'why_its_here', (select count(*)::int from venues where slug = 'linga-longa-bar' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '45d4afc7919ed460355df93da9d12de7'), md5('A live-music bar with bands every night, playing rock, pop and Top 40. The main sets start around 8:30pm, late rock sessions run past midnight, and a babi guling (suckling pig) buffet goes on Wednesdays and Sundays.') = 'dba3c8925650a0438095c09d34c3ecc2'),
  (66, 'linga-longa-bar', 'best_for', (select count(*)::int from venues where slug = 'linga-longa-bar' and status = 'active' and publication_status = 'published' and md5(best_for) = 'cb1cc68517541b69ab8e4fb58813ee5d'), md5('A night out with live music and drinks, for a group that wants to sing along and stay late') = '6f23c92cd40839e3fb1f73da12d32224'),
  (67, 'linga-longa-bar', 'not_for', (select count(*)::int from venues where slug = 'linga-longa-bar' and status = 'active' and publication_status = 'published' and md5(not_for) = '1543b934cbcc166a92b47229cfb75092'), md5(U&'A quiet dinner or an early night \2014 the bands play every night and the rock runs past midnight') = 'b814f26f7d3fe1bb7bb5f00dce22fdac'),
  (68, 'mantra-wellness', 'why_its_here', (select count(*)::int from venues where slug = 'mantra-wellness' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '9fcf66c96b502d14d7cab8078cd55b0c'), md5('A short walk from Padang Padang beach, this wellness centre pairs yoga and pilates with a sauna, cold plunge and mandala pool for recovery. There''s a healthy cafe and coworking too, and the rooms on site are adults-only.') = 'da2cbd204292c2bbe667a4bc16c1b573'),
  (69, 'mantra-wellness', 'not_for', (select count(*)::int from venues where slug = 'mantra-wellness' and status = 'active' and publication_status = 'published' and (not_for is null or length(trim(not_for)) = 0)), md5('A family stay: the rooms on site are adults-only') = '96571008d0e4b349cabcc4c8cbc13c49'),
  (70, 'marramba-fitness', 'why_its_here', (select count(*)::int from venues where slug = 'marramba-fitness' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '5e01ef74e22f4dbbedf64b54dfca5d0d'), md5('Old-school bodybuilding gym in Renon, close to Sanur. A full set of iron, personal training and clean showers. Upstairs there is a karate section for young people.') = '67555d764f2d88883c028627ca7d83da'),
  (71, 'martha-tilaar-salon-day-spa-sanur', 'why_its_here', (select count(*)::int from venues where slug = 'martha-tilaar-salon-day-spa-sanur' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'd0c33e3bbeca26a08419e9f9dc1a67e7'), md5('Martha Tilaar''s Sanur branch, where the Indonesian brand does its herbal spa rituals, plus hair, nails and beauty basics.') = '59fcb50d4d105a124c8ac0e9d1888704'),
  (72, 'martha-tilaar-salon-day-spa-sanur', 'best_for', (select count(*)::int from venues where slug = 'martha-tilaar-salon-day-spa-sanur' and status = 'active' and publication_status = 'published' and md5(best_for) = '8556b6f20b13e27bb9637a457be1089a'), md5('Herbal spa rituals from a local Indonesian brand, with hair or nails in the same visit') = 'ca76219e7e84e8aeb6c205711f931158'),
