  (76, 'maya-sanur-yoga-studio', 'best_for', (select count(*)::int from venues where slug = 'maya-sanur-yoga-studio' and status = 'active' and publication_status = 'published' and md5(best_for) = '23b8b83f11299315aa082e6691421fd0'), md5('Resort guests who want a free daily class, indoors in the cool or out on the plaza or roof') = '23b9414ab82438a19fc66c33142fa20b'),
