  (78, 'mona-lisa-cafe', 'best_for', (select count(*)::int from venues where slug = 'mona-lisa-cafe' and status = 'active' and publication_status = 'published' and md5(best_for) = 'dc482f9daf1020d8cba1d5bcfb2361e2'), md5('Families and long-stay visitors who want an easy all-rounder with familiar Indonesian dishes') = 'a0f649f8714c8cb061b1901c2a1f4f54'),
  (79, 'mona-lisa-cafe', 'not_for', (select count(*)::int from venues where slug = 'mona-lisa-cafe' and status = 'active' and publication_status = 'published' and md5(not_for) = '8a938de24983042ac1a8beddcd5aa797'), md5('A special occasion or fine dining, because this is a casual cafe') = '432b5220f5b518281a204c8f9e329607'),
