  (82, 'morning-light-yoga-studio', 'best_for', (select count(*)::int from venues where slug = 'morning-light-yoga-studio' and status = 'active' and publication_status = 'published' and md5(best_for) = 'e639674e840f3356c99446d8ee901471'), md5('A scenic sunrise class on the clifftop, with ocean views') = '7e12570408a9d42e727cfaeed23ddd28'),
  (83, 'morning-light-yoga-studio', 'not_for', (select count(*)::int from venues where slug = 'morning-light-yoga-studio' and status = 'active' and publication_status = 'published' and (not_for is null or length(trim(not_for)) = 0)), md5('A full studio timetable: there is one class a day') = '399adadc7b45aef737a1e53393a19829'),
