  (85, 'nelayan-restaurant-and-puri-bar', 'best_for', (select count(*)::int from venues where slug = 'nelayan-restaurant-and-puri-bar' and status = 'active' and publication_status = 'published' and md5(best_for) = '8bf551acc87bcf5931f40c3627dff525'), md5('Couples and resort guests after a sunset cocktail or an unhurried seafood dinner, calmer than Jimbaran''s crowded grill row') = '67feba08ec81a9169336adb6ea4f39f4'),
  (86, 'oranje-bar', 'why_its_here', (select count(*)::int from venues where slug = 'oranje-bar' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'bc65a20d4756ee120c12ee2ea17ec954'), md5('A small Dutch-run bar a short walk from Sindhu beach, pouring beer and serving Dutch bar food and snacks.') = '8b1439781febbaf94a13860f91800847'),
  (87, 'oranje-bar', 'best_for', (select count(*)::int from venues where slug = 'oranje-bar' and status = 'active' and publication_status = 'published' and md5(best_for) = '3d2db3d2bc04eda003f0697ed0b801db'), md5('A low-key beer and snacks after the beach, alone or as a couple') = '887f3dd232f677b0741fe5d882cd1daf'),
