  (89, 'ours-bali-uluwatu-bukit', 'why_its_here', (select count(*)::int from venues where slug = 'ours-bali-uluwatu-bukit' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '94c7d04339b20ab2227f0cbc6237ea13'), md5(U&'Ours Bali is an all-day restaurant and bar on the Bukit. Happy hour runs 4\20136pm daily, with discounted cocktails and wines, and you book on the venue''s own website.') = 'e6a77241128b460e58b4b2a1805e44b6'),
  (90, 'ours-bali-uluwatu-bukit', 'best_for', (select count(*)::int from venues where slug = 'ours-bali-uluwatu-bukit' and status = 'active' and publication_status = 'published' and md5(best_for) = 'f6e07c3b8e5ab01856ea4c4a218240d1'), md5('Discounted cocktails and wine at happy hour') = '0bfac0f84e02c8a889c08de2cf587f6a'),
  (91, 'ours-spa-boutique', 'why_its_here', (select count(*)::int from venues where slug = 'ours-spa-boutique' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '6327f76d16a303c05fd6bf724430287b'), md5('Dermalogica facials, nails, hair and massage at a neighbourhood day spa on Jalan Labuan Sait, with a sister cafe next door. It works largely with vegan and cruelty-free product lines.') = '56852f896445f91d313232494cdf092f'),
