  (93, 'piccolina', 'why_its_here', (select count(*)::int from venues where slug = 'piccolina' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '664e1d1f9168b489bc4954cbbf472875'), md5('Hair comes first at this salon on Jl. Labuansait: precision cuts, colour, keratin and blow-dries to European standards. Manicures and massage are available too, and the space doubles as a small wine bottle shop.') = 'df6a315ddcd73a7e3b9a57e6ce3f2bb7'),
  (94, 'piccolina', 'best_for', (select count(*)::int from venues where slug = 'piccolina' and status = 'active' and publication_status = 'published' and md5(best_for) = '60ef33f8591f00d25c9b7222447175f5'), md5('An expert cut or colour for men or women') = '0f13f4c86627541137b5901e4193dabe'),
