  (96, 'power-of-now-oasis-sanur', 'best_for', (select count(*)::int from venues where slug = 'power-of-now-oasis-sanur' and status = 'active' and publication_status = 'published' and md5(best_for) = '1faa1e0b13efaadb7ec16b5a352224a0'), md5('Daily classes on the beach in a bamboo studio, or a 200-hour teacher training or retreat') = '0d8d6c3ff57d8ac5e30d08931e1d4bb0'),
