  (98, 'puri-santrian-spa-sanur', 'best_for', (select count(*)::int from venues where slug = 'puri-santrian-spa-sanur' and status = 'active' and publication_status = 'published' and md5(best_for) = '7efc8399b1457328343eab9c1cc32ef3'), md5('Classic or modern treatments at a beachfront resort, or a massage paired with its morning beach yoga') = 'c2cf6aec9459cc522de1a159a9cefc21'),
  (99, 'puri-santrian-yoga-wellness', 'why_its_here', (select count(*)::int from venues where slug = 'puri-santrian-yoga-wellness' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '46cb1e0f1bdc79cc46b42bf9be0de9a5'), md5('Puri Santrian''s resident yoga master leads a free morning beach class of gentle stretching and breathing for in-house guests. The south Sanur resort also has a fitness suite and bicycles. Its spa uses fresh fruit, herbs and plant material alongside Sothys products.') = '3f5af1aa5395de908ad23c8fda974694'),
  (100, 'puri-santrian-yoga-wellness', 'best_for', (select count(*)::int from venues where slug = 'puri-santrian-yoga-wellness' and status = 'active' and publication_status = 'published' and md5(best_for) = '766de4d10120d71ca87254e8d54f9d06'), md5('Resort guests who want an unhurried free class on the beach in the morning') = '47514a1a2ecd5d203c1e6b28eb8d2220'),
  (101, 'puri-santrian-yoga-wellness', 'not_for', (select count(*)::int from venues where slug = 'puri-santrian-yoga-wellness' and status = 'active' and publication_status = 'published' and (not_for is null or length(trim(not_for)) = 0)), md5('A studio workout, since the class is gentle stretching and breathing on the beach') = '48213ff0b62830add9c4b9e058b6216f'),
  (102, 'raw-gym-uluwatu', 'why_its_here', (select count(*)::int from venues where slug = 'raw-gym-uluwatu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '9712c63f36bf08e3756b92f1472d2619'), md5('Raw Gym''s Uluwatu branch is an open-air warehouse-style gym with a boxing ring and a martial-arts space, on Jalan Raya Uluwatu. Coaches teach Muay Thai, boxing and BJJ alongside strength training, and membership is valid at the other Bali locations too.') = 'f703021cafc787e055e53a373086b8bd'),
  (103, 'raw-gym-uluwatu', 'best_for', (select count(*)::int from venues where slug = 'raw-gym-uluwatu' and status = 'active' and publication_status = 'published' and md5(best_for) = 'eb8efdba573f91a5b8413012b8888e40'), md5('Combat sports, or no-frills high-intensity training') = '260fa800170176f2fc7337a7ecc6fd50'),
  (104, 'reform-pilates-bali', 'why_its_here', (select count(*)::int from venues where slug = 'reform-pilates-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '9fa5e584e1755a78ee1495379764fd93'), md5('A reformer Pilates studio that opened in Bingin in 2023, then added a larger flagship near Suluban Beach with twelve reformers and a rooftop cafe. Group reformer classes run daily, alongside private sessions and duets, and class packs work at both locations.') = '42844b6aab5b0bb67180bda907eed7eb'),
  (105, 'reform-pilates-bali', 'best_for', (select count(*)::int from venues where slug = 'reform-pilates-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b90975044c1d95a32a6fd014ed30a495'), md5('Reformer Pilates regulars who want daily group classes or 1:1 sessions') = 'f51c9fd6dc8abbc5935b2cb3afcaa6ac'),
  (106, 'rose-petal', 'why_its_here', (select count(*)::int from venues where slug = 'rose-petal' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '501a3fc26732404f317a00ca2115d0b5'), md5('Hair, facials, lashes, brows, nails and body treatments under one roof, at a beauty centre on Jl. Labuansait with a lounge and a sunset terrace. Its colourists are trained in European and Asian techniques such as balayage and lived-in colour.') = 'f278da2d9b616156dd85d964f11f084e'),
  (107, 'rose-petal', 'best_for', (select count(*)::int from venues where slug = 'rose-petal' and status = 'active' and publication_status = 'published' and md5(best_for) = '2e5046ee427fc4d84337aa7bd82bdfde'), md5('Hair colour or a fuller beauty day somewhere upmarket, with a lounge to linger in') = '33ed114bd557f8dd055a28b59d0ed933'),
  (108, 'sala-bistro', 'why_its_here', (select count(*)::int from venues where slug = 'sala-bistro' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '8fdadbc59b1a5cb6e3a6a161a5705209'), md5('Specialty coffee and western-Asian comfort food at a modern bistro on Jl. Danau Tamblingan, with separate brunch and dinner menus.') = '609ba780ae7f3399f8fc943c044f9e57'),
  (109, 'sala-bistro', 'best_for', (select count(*)::int from venues where slug = 'sala-bistro' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c7e272b79030940c57ef84243ff7cb40'), md5('Brunch and coffee, or a casual daytime stop with a laptop') = '22a5f5368aa8e80cdeaee686f3617488'),
  (110, 'sala-bistro', 'not_for', (select count(*)::int from venues where slug = 'sala-bistro' and status = 'active' and publication_status = 'published' and md5(not_for) = '728f74f085cdea7641d7efaae0dabdc4'), md5('Traditional Balinese food or a large-group banquet. The menus are western-Asian comfort food') = '02203c06c87dae6b9ccef635a3db4947'),
  (111, 'segara-the-seaside', 'why_its_here', (select count(*)::int from venues where slug = 'segara-the-seaside' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '9b9471a4a253c5c4a2302cc2f4772617'), md5('A beachfront bar and restaurant right on Sanur''s shore at Jl. Segara Ayu, looking out over the ocean. Seafood, pasta, Indonesian dishes and pizza are on the menu, and there''s a beach happy hour and live music.') = '82cdc3298b12bd2927413ddb4d8851c1'),
  (112, 'segara-the-seaside', 'best_for', (select count(*)::int from venues where slug = 'segara-the-seaside' and status = 'active' and publication_status = 'published' and md5(best_for) = 'e12961f4f2e7ef1f0e5856cf01971386'), md5('Groups after beachfront tables with drinks and live music, or families eating early by the sea') = 'ec7977b8ebe4b08ff1eebc63f803ea90'),
  (113, 'segara-the-seaside', 'not_for', (select count(*)::int from venues where slug = 'segara-the-seaside' and status = 'active' and publication_status = 'published' and md5(not_for) = 'bf5daa6dc10e82b530f21842823fb5a0'), md5(U&'A quiet, music-free dinner \2014 the bar runs live music and a beach happy hour') = 'bdea3ca6688f0153dc4c287a901a317b'),
  (114, 'shankha-spa-and-fitness-at-hyatt-regency-bali', 'why_its_here', (select count(*)::int from venues where slug = 'shankha-spa-and-fitness-at-hyatt-regency-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '5b51b4c408e7ec68a7e5f921e897573e'), md5('The 24-hour gym inside Shankha Spa at Hyatt Regency Bali in Sanur has about 2,000 sq ft of Precor cardio and strength kit. The complex adds ten spa villas around a lily pond, sauna, steam, hot and cold plunge pools and a 15.5-metre lap pool.') = 'feaeadb5a81a5c7e54200179ac2d140e'),
  (115, 'shankha-spa-and-fitness-at-hyatt-regency-bali', 'best_for', (select count(*)::int from venues where slug = 'shankha-spa-and-fitness-at-hyatt-regency-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '78e49b6c897dfbaf9bf2fbdfd84e0620'), md5('A 24-hour gym with a full hydrotherapy circuit and a lap pool attached') = 'f8420b32a830a5768d5fa86c2a0041c0'),
  (116, 'shankha-spa-hyatt-regency-bali-yoga', 'why_its_here', (select count(*)::int from venues where slug = 'shankha-spa-hyatt-regency-bali-yoga' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '93db21ea9d6a163a6a5187bf2c6cb9e4'), md5('An open-air yoga studio in the Fitness Pavilion at Shankha Spa, Hyatt Regency Bali in Sanur. It sits in the spa''s garden beside the lap pool, and the schedule has a sunrise class pitched at beginners plus Hatha sessions.') = 'f29dd17768e0d799fa57c044de14f20c'),
  (117, 'shankha-spa-hyatt-regency-bali-yoga', 'best_for', (select count(*)::int from venues where slug = 'shankha-spa-hyatt-regency-bali-yoga' and status = 'active' and publication_status = 'published' and md5(best_for) = '1599e4aa6bb8d8ecdbdb7f080c47a506'), md5('A sunrise class in the open air that doesn''t assume you''ve done yoga before') = '52215db8cc6d56c5fcad3e37b90a48f4'),
  (118, 'six-senses-spa-uluwatu', 'why_its_here', (select count(*)::int from venues where slug = 'six-senses-spa-uluwatu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c7c2e85daeb609fa6c5cd0cfe0967c8f'), md5('Six Senses Uluwatu''s destination spa has treatment rooms, a yoga pavilion and a gym. It uses the Ila product line and locally inspired rituals, and builds bespoke programmes around wellness and biomarker screening.') = '66e6a12754d2f21aa85e158d9e234859'),
  (119, 'six-senses-spa-uluwatu', 'best_for', (select count(*)::int from venues where slug = 'six-senses-spa-uluwatu' and status = 'active' and publication_status = 'published' and md5(best_for) = '808d07f3583f285372227bc2627e3670'), md5('A wellness day of screening, yoga and treatments at a clifftop resort') = '2efd88728cdb21de83c80d4ffdae32ef'),
  (120, 'six-senses-uluwatu-fitness-centre', 'why_its_here', (select count(*)::int from venues where slug = 'six-senses-uluwatu-fitness-centre' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '8afeb9f78b0873be7cc17b67b503a933'), md5('The resort gym at Six Senses Uluwatu is open 24 hours. Cardio and weight machines join functional training kit, with outdoor circuits on the clifftop grounds. The wellness area around it holds treatment rooms, a relaxation lounge, spa bath, sauna and steam room.') = '5a177e8ffa0a15317ed23ac3da20c17d'),
  (121, 'six-senses-uluwatu-fitness-centre', 'best_for', (select count(*)::int from venues where slug = 'six-senses-uluwatu-fitness-centre' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b9262c1f91df82036f57bd2ede23689f'), md5('A round-the-clock gym without leaving the resort') = '77d32e8d1c8396f33e8cfccf570974b7'),
  (122, 'six-senses-uluwatu-yoga-pavilion', 'why_its_here', (select count(*)::int from venues where slug = 'six-senses-uluwatu-yoga-pavilion' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '4d2f072adbc637ab178f31525470e8c4'), md5('An air-conditioned yoga pavilion at Six Senses Uluwatu. Daily meditation and an intro-to-yoga session, 30 minutes each, are included for resort guests. Longer 45 to 60 minute sessions, such as Yoga Nidra, traditional yoga and a yogic intestinal cleanse, cost extra.') = 'a7dc28cac2dde1f4fb03ceff83d1f2a5'),
  (123, 'six-senses-uluwatu-yoga-pavilion', 'best_for', (select count(*)::int from venues where slug = 'six-senses-uluwatu-yoga-pavilion' and status = 'active' and publication_status = 'published' and md5(best_for) = '1376c65b8885e0665066ca6eeebba441'), md5('Resort guests after a daily indoor practice out of the Bukit heat, with free short sessions and longer paid ones') = 'cb6ede9389ee5d453563f731d041fc6e'),
  (124, 'snowcat-bali-ussr-cuisine', 'why_its_here', (select count(*)::int from venues where slug = 'snowcat-bali-ussr-cuisine' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'cca32595ddc8ac31c0f3a52b80ee7454'), md5('Pelmeni, olivier, draniki and herring under a fur coat come out of this post-Soviet kitchen on Jl. Raya Uluwatu in Ungasan. Portions are large, with homemade infusions to drink. It does delivery as well as dine-in and bookings.') = '6a4b7faea6fa753a049c8775ac6c3889'),
  (125, 'soul-on-the-beach', 'why_its_here', (select count(*)::int from venues where slug = 'soul-on-the-beach' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '10596da9e6e2e40e42d64dcb947270e2'), md5('Breakfast to dinner on Sindhu Beach: this beachfront restaurant next to INNA Sindhu Beach Hotel in Sanur serves Indonesian, Asian and Western food. The white-sand beach is swimmable, and the view runs to Mount Agung and Nusa Penida. Vegetarian and vegan options are available.') = '33c3f64a0edbee5d618880c81ff85dcc'),
  (126, 'soul-on-the-beach', 'best_for', (select count(*)::int from venues where slug = 'soul-on-the-beach' and status = 'active' and publication_status = 'published' and md5(best_for) = '520a39664962c7b0b04a1cb59c4a9d4d'), md5('Families and groups eating on the beach from breakfast to an early dinner, with a swim in between') = '243f81e42d6c524b3b4a1099cca4c050'),
  (127, 'soul-on-the-beach', 'not_for', (select count(*)::int from venues where slug = 'soul-on-the-beach' and status = 'active' and publication_status = 'published' and md5(not_for) = '879b69bd953f6d0ef0a44922e17af5b1'), md5('A formal, fine-dining setting. This is an all-day beach restaurant') = 'bd89e21fd5e01ad2a73d17877d1f23f4'),
  (128, 'spa-at-mu', 'why_its_here', (select count(*)::int from venues where slug = 'spa-at-mu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'b9f4e4ad7aeba234ad4f078551d37db1'), md5('An open-air cliffside spa at Mu Bali resort that looks over Bingin beach and the Impossibles surf break. Massages are done al fresco with natural and organic oils, facing the ocean and a temple.') = 'd1f6445853b2e736a11a918ae2e7e600'),
  (129, 'spa-at-mu', 'best_for', (select count(*)::int from venues where slug = 'spa-at-mu' and status = 'active' and publication_status = 'published' and md5(best_for) = 'eaa802b7a784b4d2d3baf7936ce5f911'), md5('A scenic outdoor massage on the Bingin cliffs, for a couple or a surfer') = 'c06b32f90064c0d3a3f9885b4671f864'),
  (130, 'spring-spa-uluwatu', 'why_its_here', (select count(*)::int from venues where slug = 'spring-spa-uluwatu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'a947f1988a8abedbfa7a8b283caa69e9'), md5('Treatment rooms, a Davines hair salon and mani-pedi stations make up this day spa on Jalan Labuan Sait. It uses brands such as CODAGE Paris and Davines.') = '39f555f60af12481df91936aed733f1b'),
  (131, 'spring-spa-uluwatu', 'best_for', (select count(*)::int from venues where slug = 'spring-spa-uluwatu' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b0e7dde53220290894d5f33cf1f1ca5e'), md5('Massage, facials, hair and nails on the same visit in central Uluwatu') = 'bde97e10726c2b2be599ed272f97f7b5'),
  (132, 'studio-fondue', 'why_its_here', (select count(*)::int from venues where slug = 'studio-fondue' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'ee8c315ae0399f37600a51a14bdf0a47'), md5('A design-led Pilates studio in Uluwatu that teaches Reformer, Mat and Barre classes. A drop-in class starts from 250K IDR.') = 'a8e3f27fede97d3d322f9362eae07cb9'),
  (133, 'studio-fondue', 'best_for', (select count(*)::int from venues where slug = 'studio-fondue' and status = 'active' and publication_status = 'published' and md5(best_for) = '8c2b505826314c66fcb1f7cd01373e02'), md5('Pilates-goers after a design-led studio for reformer or mat sessions') = '1791ead0713a8dde10bb904eec68ba45'),
  (134, 'sudajiva-spa-at-sudamala-sanur-sanur', 'why_its_here', (select count(*)::int from venues where slug = 'sudajiva-spa-at-sudamala-sanur-sanur' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '3e4dad96faebdd388888c8150e2c7a18'), md5('Sudajiva Spa ("Water of Life") is the 572 sqm spa at Sudamala Suites & Villas Sanur. It mixes traditional and modern healing techniques in an intimate boutique-resort setting.') = '5922f7f7d07fe23fe9ce175668ddf52b'),
  (135, 'sudajiva-spa-at-sudamala-sanur-sanur', 'best_for', (select count(*)::int from venues where slug = 'sudajiva-spa-at-sudamala-sanur-sanur' and status = 'active' and publication_status = 'published' and md5(best_for) = 'f46433d15bfc85153753ae55d99aa28a'), md5('A resort spa ritual somewhere quiet, away from Sanur''s busier stretches') = '93280281567dd3e7159a819bd5982976'),
  (136, 'sudamala-resort-sanur-wellness-yoga-sanur', 'why_its_here', (select count(*)::int from venues where slug = 'sudamala-resort-sanur-wellness-yoga-sanur' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'ecdc62c8f6f5fb20a813992b78497655'), md5('Sudamala Suites & Villas Sanur runs its wellness and yoga programme from a garden Yoga Pavilion, with instructor-led classes and evening meditation. Longer holistic journeys in the Balinese tradition include melukat purification and jamu and boreh workshops.') = '2e13ce063c576d41571ce0c1178785ab'),
  (137, 'sudamala-resort-sanur-wellness-yoga-sanur', 'best_for', (select count(*)::int from venues where slug = 'sudamala-resort-sanur-wellness-yoga-sanur' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c0566761d93659d31cc324f579b11c08'), md5('Gentle garden yoga and meditation, or a full-day holistic Balinese wellness journey') = '45d85a671ff5799c8cb845b20dc787d6'),
  (138, 'supreme-indian-restaurant', 'why_its_here', (select count(*)::int from venues where slug = 'supreme-indian-restaurant' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'fa0abecd9b0cfaf99c020f210e460dc4'), md5('North and South Indian cooking on Jl. Raya Uluwatu in Ungasan, in an air-conditioned dining room with a bar. Tandoor dishes and curries share the menu with a broad vegetarian and vegan list.') = '520467e54790ab839caa2944042eadc6'),
  (139, 'supreme-indian-restaurant', 'best_for', (select count(*)::int from venues where slug = 'supreme-indian-restaurant' and status = 'active' and publication_status = 'published' and md5(best_for) = 'd11704116fc2aea3ba16f74df62e5393'), md5('A comfortable sit-down Indian dinner in Uluwatu, vegetarians included') = '9a94651f3bd7b702f461286ebc7e8939'),
  (140, 'svaha-spa-bingin', 'why_its_here', (select count(*)::int from venues where slug = 'svaha-spa-bingin' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '36fc691cdccd791affae78d85f9c4a66'), md5('A cliffside day spa above Bingin with ocean views, doing Balinese massage, scrubs and jacuzzi rituals. Its focus is sustainable and holistic.') = 'd803cf6fbaeecf07684965e5d9f4cf1f'),
  (141, 'svaha-spa-bingin', 'best_for', (select count(*)::int from venues where slug = 'svaha-spa-bingin' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c7f825a398d036ec6abac0d7c65bf20d'), md5('An ocean-view treatment near Bingin and Impossibles, after a surf or a day on the beach') = 'ae9240656572044c5470f4995e91661f'),
  (142, 'taru-pramana-spa-sanur', 'why_its_here', (select count(*)::int from venues where slug = 'taru-pramana-spa-sanur' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '9cd91bf24a36e35b1f7e04e2f15e1cc1'), md5('The Meru Sanur''s day spa takes non-guests if they book 24 hours ahead, and it''s open daily from 9am to 9pm. Treatments include Balinese massage, singing-bowl sessions and longer ritual packages.') = '6c18fc4c43907ac9875bdebc44ba73b2'),
  (143, 'taru-pramana-spa-sanur', 'best_for', (select count(*)::int from venues where slug = 'taru-pramana-spa-sanur' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b3a6b3a41e73d53e78dd589c6b42ea25'), md5('A booked spa ritual or massage in Sanur, with Swissline facials among the options') = 'de7ac609cbcb124cda16b5b4acbef392'),
  (144, 'terrace-sanur-the-1o1-bali-oasis-sanur', 'why_its_here', (select count(*)::int from venues where slug = 'terrace-sanur-the-1o1-bali-oasis-sanur' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'b018796f717e478b98e5abf1339f7428'), md5('Terrace Sanur is the restaurant of THE 1O1 hotel on Jalan Danau Tamblingan. The hotel is laid out around a lagoon-style pool and landscaped grounds.') = '7f0ac8cf3d18ac1c9892d5868a7be70e'),
  (145, 'terrace-sanur-the-1o1-bali-oasis-sanur', 'best_for', (select count(*)::int from venues where slug = 'terrace-sanur-the-1o1-bali-oasis-sanur' and status = 'active' and publication_status = 'published' and md5(best_for) = '7e02ce1aa158591ebf62e7c81c82b793'), md5('A hotel meal during a stay in central Sanur') = '7d35b60e0884ac2476ed0ad16ca38ae7'),
  (146, 'terrace-sanur-the-1o1-bali-oasis-sanur', 'not_for', (select count(*)::int from venues where slug = 'terrace-sanur-the-1o1-bali-oasis-sanur' and status = 'active' and publication_status = 'published' and md5(not_for) = '33dea92e42a990e89ec5613d4c0a2d5c'), md5('An independent street-side venue, or a meal when you''re not staying in Sanur: this is a hotel restaurant') = '7cce5360b190893f053f2dba983cceba'),
  (147, 'the-asa-maia', 'why_its_here', (select count(*)::int from venues where slug = 'the-asa-maia' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'a1a1433cf30112b5d05f47c671b23b5f'), md5('An adults-only wellness retreat in Uluwatu with a small spa, contrast therapy, an infrared sauna and hot and cold plunge pools. It uses local and natural products.') = 'd76cff9ba5d7dc78807d70767d406029'),
  (148, 'the-asa-maia', 'best_for', (select count(*)::int from venues where slug = 'the-asa-maia' and status = 'active' and publication_status = 'published' and md5(best_for) = '128e7c79b557f184d11025090613acc7'), md5('Contrast therapy, yoga and a massage in one visit') = '7d534894e3dbf57c2a85c47fd74e76c9'),
  (149, 'the-asa-maia-fitness', 'why_its_here', (select count(*)::int from venues where slug = 'the-asa-maia-fitness' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '2e7ad38333ab95ade3eb51f34bde1a97'), md5('The Asa Maia, a family-owned adults-only wellness retreat in Uluwatu opened in 2021, has its gym in the central pavilion. The kit: treadmill, power rack, barbell, kettlebells, dumbbells, slam balls, a stepper, a TRX system and a Pilates Cadillac. An infrared sauna is on site.') = '736c8b12d3e427a2cd482004a932d4d8'),
  (150, 'the-asa-maia-fitness', 'best_for', (select count(*)::int from venues where slug = 'the-asa-maia-fitness' and status = 'active' and publication_status = 'published' and md5(best_for) = 'f31e663988079cae6958ba5cee01ae74'), md5('Strength training with real equipment during a structured wellness stay') = '1624b1765b8d04b1eeb53bc8e3acfb58'),
  (151, 'the-asa-maia-pilates', 'best_for', (select count(*)::int from venues where slug = 'the-asa-maia-pilates' and status = 'active' and publication_status = 'published' and md5(best_for) = '83d8f4cabf45dafd4647019e8952b4d9'), md5('Retreat guests who want daily pilates as part of a structured programme, including work on the Cadillac') = '2f43f22ace30ab51ba7862677e5a2ca9'),
  (152, 'the-asa-maia-yoga', 'why_its_here', (select count(*)::int from venues where slug = 'the-asa-maia-yoga' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '35749af8f136d9bc10acf3cbfbd8c9d5'), md5('Daily yoga at The Asa Maia, in a shala on the top level of the central pavilion. Instructors teach Hatha, Yin and Vinyasa, adapted to each guest''s level. SOMA breathwork is the retreat''s own practice; Indonesian martial arts and Qi Gong are also taught.') = '43e293e494a18e8cdaad22892667f8b0'),
  (153, 'the-asa-maia-yoga', 'best_for', (select count(*)::int from venues where slug = 'the-asa-maia-yoga' and status = 'active' and publication_status = 'published' and md5(best_for) = '8d58a9b2cde9ff4d90b16a016f6aa846'), md5('Daily guided practice matched to your level, during a wellness stay in Uluwatu') = '7a63d8238ffa71559f8624858e154ae8'),
  (154, 'the-asa-maia-yoga', 'not_for', (select count(*)::int from venues where slug = 'the-asa-maia-yoga' and status = 'active' and publication_status = 'published' and (not_for is null or length(trim(not_for)) = 0)), md5('A drop-in class on a fixed schedule: practice here is guided and matched to each guest''s level') = '8e2b93e2e2f3476e102c264eb6f49b14'),
  (155, 'the-bvlgari-spa', 'why_its_here', (select count(*)::int from venues where slug = 'the-bvlgari-spa' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '682e58b81503bbef568b0977fc3bc020'), md5('Bvlgari Resort Bali''s spa occupies a reconstructed antique Javanese joglo on the Uluwatu cliff, about 150m above the sea, with eight whirlpool treatment rooms. The Royal Lulur couples ritual is on the menu, and treatments can also be done by the beach.') = '6fc477f3593bf72c248ae2deb4f4fa19'),
  (156, 'the-bvlgari-spa', 'best_for', (select count(*)::int from venues where slug = 'the-bvlgari-spa' and status = 'active' and publication_status = 'published' and md5(best_for) = 'a4eead1ec35ca27af6cc31dbda819323'), md5('Luxury travellers after a high-end ritual on the cliff or by the beach') = 'c3481df0a1d96f90b765d12474212a59'),
