  (159, 'the-istana-yoga', 'why_its_here', (select count(*)::int from venues where slug = 'the-istana-yoga' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'a7e62e0bd7d2f2b9d44d2f5b8e527e35'), md5('The Istana''s yoga programme on the Uluwatu cliffs has around 20 class formats, from Vinyasa and Qigong to Rebirthing Breathwork and Yoga Nidra. Instructors are internationally trained, teacher training runs in 200- and 300-hour formats, and drop-ins start from 150,000 IDR.') = '1e5bbc2c2e5569a4900a5cc82850b8fb'),
  (160, 'the-istana-yoga', 'best_for', (select count(*)::int from venues where slug = 'the-istana-yoga' and status = 'active' and publication_status = 'published' and md5(best_for) = '88ccfda4545b88739c4c02b31e410035'), md5('A wide range of styles and a route into teacher training, with the donation-based Sunday class as a low-cost way in') = 'e7a818b950c932cb6d8df23c973858df'),
  (161, 'the-space-bali', 'why_its_here', (select count(*)::int from venues where slug = 'the-space-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '74cc5328a4f564e947f4185689095202'), md5('A community hub in the Bingin and Uluwatu area with two bamboo shalas upstairs and a coworking cafe downstairs. The daily schedule is broad: vinyasa, yin, mobility and surf-mobility classes, plus teacher trainings.') = '61b80cf55da8f571ba882c6a99fcceac'),
  (162, 'the-space-bali', 'best_for', (select count(*)::int from venues where slug = 'the-space-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = 'f74bc9c8705ca61e14fb50e7a4982eb9'), md5('Digital nomads and longer-stay travellers who want daily classes and a base for work and yoga') = '57aafd12e3c9b35615be4e46a12e8504'),
  (163, 'the-temple-lodge', 'why_its_here', (select count(*)::int from venues where slug = 'the-temple-lodge' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '6c47f996933b7ddfbf7eea1ebd0b0840'), md5('A family-run guesthouse set up for surf and yoga, on the Bingin clifftop above Impossibles and Bingin. Its clifftop shala holds daily yoga that outside guests can join, and the spa and healthy restaurant are on site.') = 'df01e0ccf3b61b86e0fffee4fbee5093'),
  (164, 'the-temple-lodge', 'best_for', (select count(*)::int from venues where slug = 'the-temple-lodge' and status = 'active' and publication_status = 'published' and md5(best_for) = '6f63afda10ccd4f14c34fdd66c9edffc'), md5('Surfers and couples who want clifftop yoga built into their stay') = 'c80a85b460f97661cd89fc5994c0ff46'),
