  (168, 'ulu-active-recovery', 'best_for', (select count(*)::int from venues where slug = 'ulu-active-recovery' and status = 'active' and publication_status = 'published' and md5(best_for) = '4c8e9916698ef341248733eff0ced772'), md5('Training and structured recovery in one visit') = '8cd5931826c42f6e2710d5dde84dc63d'),
