  (170, 'ulu-yoga-bali', 'best_for', (select count(*)::int from venues where slug = 'ulu-yoga-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '6711fa8f09e0e0d11504ff9dd02d5d4e'), md5('Teacher training, or structured multi-style practice that includes aerial and acro') = 'bb39e36bbf97274c9b9718948a0fd361'),
